    }
  }
];

const accounts = $input.all();

const healthScores = {
  "ACC-001": {
    health_score: 32,
    risk_level: "high",
    churn_probability: 0.74,
    key_risks: "Low feature adoption; 14 days since last login; high ticket volume; declining usage trend",
    recommended_actions: "Schedule executive business review; assign dedicated onboarding support; offer feature training session"
  },
  "ACC-002": {
    health_score: 91,
    risk_level: "low",
    churn_probability: 0.05,
    key_risks: "No significant risks identified",
    recommended_actions: "Identify expansion opportunity; request case study or referral"
  },
  "ACC-003": {
    health_score: 18,
    risk_level: "critical",
    churn_probability: 0.89,
    key_risks: "30 days since last login; very low adoption; 12 open tickets; NPS score 4; renewal in 60 days",
    recommended_actions: "Escalate to CSM leadership immediately; schedule emergency health call; review implementation gaps"
  }
};

return accounts.map(item => {
  const account = item.json;
  const scores = healthScores[account.account_id];
  return {
    json: {
      ...account,
      ...scores,
      needs_alert: scores.risk_level === "high" || scores.risk_level === "critical",
      analyzed_at: new Date().toISOString()
    }
  };
});
